const msg = $input.first().json.message || $input.first().json;
const chatId = String(msg.chat && msg.chat.id ? msg.chat.id : '');
const text = String(msg.text || '').trim();
const up = text.toUpperCase();
const isId = /^S1-\d{4}/i.test(text);
const isQuiz = !isId && /[A-D]/.test(up);
return [{ json: { chatId, text, isId, isQuiz } }];

const msg = $('Read message').first().json;
const raw = msg.text.trim();
const studentID = raw.split(/\s+/)[0].toUpperCase();
const hint = raw.split(/\s+/).slice(1).join(' ').toLowerCase();
const students = $('Get students').all().map((i) => i.json);
const student = students.find((s) => String(s.studentID).toUpperCase() === studentID);
if (!student) {
  return [{ json: { chatId: msg.chatId, outText: 'ID not found. Try S1-1001', skip: true } }];
}
let subject = String(student.currentSubject || '').trim();
if (hint) {
  const hit = $('Get lessons').all().map((i) => i.json).find((l) => String(l.subjectName).toLowerCase().includes(hint));
  if (hit) subject = hit.subjectName;
}
if (!subject) subject = 'Integrated Sciences';
const lessons = $('Get lessons').all().map((i) => i.json)
  .filter((l) => String(l.subjectName) === subject)
  .sort((a, b) => Number(a.lessonNumber) - Number(b.lessonNumber));
let n = Number(student.currentLesson || 0);
if (String(student.lastResult) === 'Pass') n = n + 1;
if (!n) n = 1;
const lesson = lessons.find((l) => Number(l.lessonNumber) === n) || lessons[0];
if (!lesson) {
  return [{ json: { chatId: msg.chatId, outText: `Hi ${student.firstName}. No more lessons in ${subject}.`, skip: true } }];
}
const retry = String(student.lastResult) === 'Fail';
const easy = retry ? '\nThis is a simpler retry of the same lesson.' : '';
const outText = `Hi ${student.firstName}.\n\nSubject: ${lesson.subjectName}\nLesson ${lesson.lessonNumber}: ${lesson.lessonTitle}${easy}\n\n${lesson.materialText}\n\nQuiz — reply with 3 letters only, example:\nC B A\n\n1) ${lesson.quizQ1}\n2) ${lesson.quizQ2}\n3) ${lesson.quizQ3}\n\nPass = ${lesson.passMark} or more out of 9.`;
return [{ json: {
  skip: false,
  chatId: msg.chatId,
  studentID: student.studentID,
  firstName: student.firstName,
  lastName: student.lastName,
  subjectName: lesson.subjectName,
  lessonID: lesson.lessonID,
  lessonNumber: Number(lesson.lessonNumber),
  passMark: Number(lesson.passMark || 5),
  outText,
}}];

const msg = $('Read message').first().json;
const chatId = String(msg.chatId);
const students = $('Get students for quiz').all().map((i) => i.json);
const student = students.find((s) => String(s.telegramChatID) === chatId) || students.find((s) => String(s.telegramChatID) === String(chatId));
if (!student || !student.currentLesson) {
  return [{ json: { chatId, outText: 'Send your ID first, example: S1-1001', skip: true } }];
}
const lesson = $('Get lessons for quiz').all().map((i) => i.json).find((l) =>
  String(l.subjectName) === String(student.currentSubject) && Number(l.lessonNumber) === Number(student.currentLesson)
);
if (!lesson) {
  return [{ json: { chatId, outText: 'No open lesson. Send your ID first.', skip: true } }];
}
const letters = String(msg.text).toUpperCase().replace(/[^A-D]/g, ' ').trim().split(/\s+/).filter(Boolean);
let score = 0;
if (letters[0] === String(lesson.quizA1).toUpperCase()) score += 3;
if (letters[1] === String(lesson.quizA2).toUpperCase()) score += 3;
if (letters[2] === String(lesson.quizA3).toUpperCase()) score += 3;
const passMark = Number(lesson.passMark || 5);
const result = score >= passMark ? 'Pass' : 'Fail';
const nextTip = result === 'Pass'
  ? 'Well done. Send your ID again for the next lesson.'
  : 'Try the same lesson again. Send your ID. You will get a simpler explanation.';
return [{ json: {
  skip: false,
  chatId,
  studentID: student.studentID,
  firstName: student.firstName,
  lastName: student.lastName,
  subjectName: lesson.subjectName,
  lessonID: lesson.lessonID,
  lessonNumber: Number(lesson.lessonNumber),
  score,
  result,
  outText: `Hi ${student.firstName}.\nScore: ${score}/9\nResult: ${result}\n\n${nextTip}`,
}}];
